import sys
from fractions import Fraction

def main():
    n = int(sys.stdin.read().strip())
    if n == 1:
        print("1/1")
    else:
        expected_tosses = Fraction(n - 1, n - 1)
        for i in range(2, n):
            expected_tosses += Fraction(1, i * (i - 1))
        print(expected_tosses)

main()
